func patternAtom(source string, at int) (*Atom, int, string) {
	c := source[at]
	if c == '*' || c == 'A' || c == 'a' {
		return &Atom{Wildcard: c}, at + 1, ""
	}
	if c == '[' {
		end := strings.IndexByte(source[at+1:], ']')
		if end < 0 {
			return nil, at, "unclosed bracket"
		}
		end += at + 1
		parts := strings.Split(source[at+1:end], ",")
		atom := &Atom{}
		for _, part := range parts {
			if part == "" {
				return nil, at, "bad bracket atom"
			}
			a, next, ok := organic(part, 0)
			if !ok || next != len(part) {
				return nil, at, "bad bracket atom"
			}
			atom.Choices = append(atom.Choices, Choice{a.Symbol, a.Aromatic})
		}
		return atom, end + 1, ""
	}
	a, next, ok := organic(source, at)
	if !ok {
		return nil, at, "unexpected character"
	}
	a.Choices = []Choice{{a.Symbol, a.Aromatic}}
	return a, next, ""
}
func atomMatches(pattern, molecule *Atom) bool {
	switch pattern.Wildcard {
	case '*':
		return true
	case 'A':
		return !molecule.Aromatic
	case 'a':
		return molecule.Aromatic
	}
	for _, c := range pattern.Choices {
		if c.Symbol == molecule.Symbol && c.Aromatic == molecule.Aromatic {
			return true
		}
	}
	return false
}
func bondMatches(pattern, molecule *Bond) bool { return pattern.Match&(1<<molecule.Type) != 0 }
func moleculePattern(m *Molecule) *Molecule {
	p := &Molecule{}
	for _, a := range m.Atoms {
		p.Atoms = append(p.Atoms, &Atom{Choices: []Choice{{a.Symbol, a.Aromatic}}})
	}
	for _, b := range m.Bonds {
		p.Bonds = append(p.Bonds, &Bond{A: b.A, B: b.B, Match: 1 << b.Type})
	}
	p.Build()
	return p
}

type Embeddings struct {
	Count, Unique int
	First         []int
}

func embeddings(pattern, molecule *Molecule) Embeddings {
	out := Embeddings{}
	if len(pattern.Atoms) > len(molecule.Atoms) {
		return out
	}
	mapping := make([]int, len(pattern.Atoms))
	for i := range mapping {
		mapping[i] = -1
	}
	used := make([]bool, len(molecule.Atoms))
	sets := map[string]bool{}
	var search func(int)
	search = func(index int) {
		if index == len(pattern.Atoms) {
			out.Count++
			if out.First == nil {
				out.First = make([]int, len(mapping))
				for i, a := range mapping {
					out.First[i] = a + 1
				}
			}
			mask := new(big.Int)
			for _, a := range mapping {
				mask.SetBit(mask, a, 1)
			}
			sets[mask.Text(16)] = true
			return
		}
		for candidate, a := range molecule.Atoms {
			if used[candidate] || !atomMatches(pattern.Atoms[index], a) {
				continue
			}
			valid := true
			for _, e := range pattern.Adjacent[index] {
				b := pattern.Bonds[e]
				other := b.Other(index)
				if other >= index {
					continue
				}
				actual := molecule.Bond(candidate, mapping[other])
				if actual == nil || !bondMatches(b, actual) {
					valid = false
					break
				}
			}
			if valid {
				mapping[index] = candidate
				used[candidate] = true
				search(index + 1)
				used[candidate] = false
				mapping[index] = -1
			}
		}
	}
	search(0)
	out.Unique = len(sets)
	return out
}
func fingerprint(m *Molecule, elements map[string]Element) {
	codes := make([]int, len(m.Atoms))
	for i, a := range m.Atoms {
		aromatic := 0
		if a.Aromatic {
			aromatic = 8
		}
		codes[i] = 16*elements[a.Symbol].Number + aromatic + len(m.Adjacent[i])
	}
	visited := make([]bool, len(m.Atoms))
	var visit func(int, int, int)
	visit = func(a, depth, hash int) {
		m.Paths++
		m.Bits[hash%1024] = true
		if depth == 5 {
			return
		}
		for _, e := range m.Adjacent[a] {
			b := m.Bonds[e]
			next := b.Other(a)
			if visited[next] {
				continue
			}
			value := (hash*31 + b.Type) % 1000003
			value = (value*31 + codes[next]) % 1000003
			visited[next] = true
			visit(next, depth+1, value)
			visited[next] = false
		}
	}
	for i := range m.Atoms {
		visited[i] = true
		visit(i, 0, codes[i])
		visited[i] = false
	}
	for _, bit := range m.Bits {
		if bit {
			m.BitCount++
		}
	}
}

type Fraction struct{ N, D int }

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
func fraction(n, d int) Fraction {
	g := gcd(n, d)
	return Fraction{n / g, d / g}
}
func (a Fraction) Cmp(b Fraction) int {
	left, right := a.N*b.D, b.N*a.D
	if left < right {
		return -1
	}
	if left > right {
		return 1
	}
	return 0
}
func similarity(a, b *Molecule) (Fraction, int, int) {
	common, union := 0, 0
	for i := range a.Bits {
		if a.Bits[i] && b.Bits[i] {
			common++
		}
		if a.Bits[i] || b.Bits[i] {
			union++
		}
	}
	return fraction(common, union), common, union
}
func distinctStrings(a []string) int {
	copy := slices.Clone(a)
	slices.Sort(copy)
	return len(slices.Compact(copy))
}

package main

import "strings"

func digit(c byte) bool { return c >= '0' && c <= '9' }
func organic(source string, at int) (*Atom, int, bool) {
	if at+1 < len(source) && (source[at:at+2] == "Cl" || source[at:at+2] == "Br") {
		return &Atom{Symbol: source[at : at+2]}, at + 2, true
	}
	c := source[at]
	if strings.ContainsRune("BCNOPSFI", rune(c)) {
		return &Atom{Symbol: string(c)}, at + 1, true
	}
	if strings.ContainsRune("bcnops", rune(c)) {
		return &Atom{Symbol: strings.ToUpper(string(c)), Aromatic: true}, at + 1, true
	}
	return nil, at, false
}
func bracket(content string, elements map[string]Element) (*Atom, string) {
	a := &Atom{Bracket: true}
	i := 0
	for i < len(content) && digit(content[i]) {
		i++
	}
	if i >= 4 || (i > 0 && content[0] == '0') {
		return nil, "bad bracket atom"
	}
	if i > 0 {
		a.Mass = integer(content[:i])
	}
	if i == len(content) {
		return nil, "bad bracket atom"
	}
	c := content[i]
	if strings.ContainsRune("bcnops", rune(c)) {
		a.Symbol = strings.ToUpper(string(c))
		a.Aromatic = true
		i++
	} else if c >= 'A' && c <= 'Z' {
		if i+1 < len(content) && content[i+1] >= 'a' && content[i+1] <= 'z' {
			if _, ok := elements[content[i:i+2]]; ok {
				a.Symbol = content[i : i+2]
				i += 2
			}
		}
		if a.Symbol == "" {
			symbol := string(c)
			if _, ok := elements[symbol]; !ok {
				return nil, "unknown element"
			}
			a.Symbol = symbol
			i++
		}
	} else {
		return nil, "bad bracket atom"
	}
	if strings.HasPrefix(content[i:], "@@") {
		i += 2
	} else if i < len(content) && content[i] == '@' {
		i++
	}
	if i < len(content) && content[i] == 'H' {
		a.Hydrogens = 1
		i++
		if i < len(content) && digit(content[i]) {
			a.Hydrogens = int(content[i] - '0')
			i++
		}
	}
	if i < len(content) && (content[i] == '+' || content[i] == '-') {
		sign := 1
		if content[i] == '-' {
			sign = -1
		}
		i++
		magnitude := 1
		if i < len(content) && content[i] >= '1' && content[i] <= '9' {
			magnitude = int(content[i] - '0')
			i++
		}
		a.Charge = sign * magnitude
	}
	if i != len(content) {
		return nil, "bad bracket atom"
	}
	return a, ""
}
func symbolType(c byte) int {
	switch c {
	case '-', '/', '\\':
		return 1
	case '=':
		return 2
	case '#':
		return 3
	case ':':
		return 4
	case '~':
		return 5
	}
	return 0
}
func bondSymbol(c byte, pattern bool) bool {
	if pattern {
		return strings.ContainsRune("-=#:~", rune(c))
	}
	return strings.ContainsRune("-/\\=#:", rune(c))
}

type Branch struct{ Atom, Column int }
type OpenRing struct {
	Atom, Column int
	Symbol       byte
}

func parseSMILES(source string, elements map[string]Element, pattern bool) (*Molecule, *ParseError) {
	m := &Molecule{}
	current := -1
	pending := byte(0)
	pendingColumn := 0
	stack := []Branch{}
	open := map[int]OpenRing{}
	existing := map[[2]int]bool{}
	fail := func(reason string, column int) (*Molecule, *ParseError) { return nil, &ParseError{reason, column} }
	addBond := func(a, b int, symbol byte) {
		if a > b {
			a, b = b, a
		}
		bond := &Bond{A: a, B: b, Symbol: symbol}
		if pattern {
			kind := symbolType(symbol)
			if kind == 0 {
				bond.Match = (1 << 1) | (1 << 4)
			} else if kind == 5 {
				bond.Match = (1 << 1) | (1 << 2) | (1 << 3) | (1 << 4)
			} else {
				bond.Match = 1 << kind
			}
		}
		m.Bonds = append(m.Bonds, bond)
		existing[[2]int{a, b}] = true
	}
	for i := 0; i < len(source); {
		c := source[i]
		column := i + 1
		switch {
		case bondSymbol(c, pattern):
			if current < 0 || pending != 0 {
				return fail("misplaced bond", column)
			}
			pending = c
			pendingColumn = column
			i++
		case c == '(':
			if current < 0 || pending != 0 || (i > 0 && source[i-1] == '(') {
				return fail("misplaced branch", column)
			}
			stack = append(stack, Branch{current, column})
			i++
		case c == ')':
			if len(stack) == 0 {
				return fail("unmatched parenthesis", column)
			}
			if pending != 0 {
				return fail("dangling bond", pendingColumn)
			}
			if i > 0 && source[i-1] == '(' {
				return fail("empty branch", column)
			}
			last := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			current = last.Atom
			i++
		case digit(c) || c == '%':
			if current < 0 {
				return fail("misplaced ring closure", column)
			}
			number := 0
			if c == '%' {
				if i+2 >= len(source) || !digit(source[i+1]) || !digit(source[i+2]) {
					return fail("bad ring number", column)
				}
				number = integer(source[i+1 : i+3])
				i += 3
			} else {
				number = int(c - '0')
				i++
			}
			symbol := pending
			pending = 0
			if old, ok := open[number]; ok {
				if old.Atom == current {
					return fail("self bond", column)
				}
				if old.Symbol != 0 && symbol != 0 {
					same := old.Symbol == symbol
					if !pattern {
						same = symbolType(old.Symbol) == symbolType(symbol)
					}
					if !same {
						return fail("ring bond mismatch", column)
					}
				}
				a, b := old.Atom, current
				if a > b {
					a, b = b, a
				}
				if existing[[2]int{a, b}] {
					return fail("duplicate bond", column)
				}
				if symbol == 0 {
					symbol = old.Symbol
				}
				addBond(old.Atom, current, symbol)
				delete(open, number)
			} else {
				open[number] = OpenRing{current, column, symbol}
			}
		default:
			var atom *Atom
			var next int
			var reason string
			if pattern {
				atom, next, reason = patternAtom(source, i)
			} else if c == '[' {
				end := strings.IndexByte(source[i+1:], ']')
				if end < 0 {
					return fail("unclosed bracket", column)
				}
				end += i + 1
				atom, reason = bracket(source[i+1:end], elements)
				next = end + 1
			} else {
				var ok bool
				atom, next, ok = organic(source, i)
				if !ok {
					reason = "unexpected character"
				}
			}
			if reason != "" {
				return fail(reason, column)
			}
			atom.Column = column
			m.Atoms = append(m.Atoms, atom)
			index := len(m.Atoms) - 1
			if current >= 0 {
				addBond(current, index, pending)
			}
			current = index
			pending = 0
			i = next
		}
	}
	if pending != 0 {
		return fail("dangling bond", pendingColumn)
	}
	if len(stack) > 0 {
		return fail("unmatched parenthesis", stack[0].Column)
	}
	if len(open) > 0 {
		column := len(source) + 1
		for _, r := range open {
			column = min(column, r.Column)
		}
		return fail("unclosed ring", column)
	}
	m.Build()
	return m, nil
}
